WITH employees_by_department AS (SELECT dept_id, ROUND(AVG(salary), 2) AS avg_salary FROM employees GROUP BY dept_id) SELECT d.location, d.dept_name, ebd.avg_salary FROM departments d LEFT JOIN employees_by_department ebd ON d.id = ebd.dept_id WHERE ebd.avg_salary >= 56 ORDER BY d.location DESC, avg_salary DESC;
